# Lambda grid — autotuner XBLOCK controls block count
grid = lambda meta: (triton.cdiv(xnumel, meta['XBLOCK']),)  # e.g. 7840 blocks with XBLOCK=1
kernel[grid](...)

@triton.autotune(configs=[Config({'XBLOCK': 1}, num_stages=2), ..., Config({'XBLOCK': 128}, num_stages=2)], key=['xnumel'])
@triton.jit
def kernel(...):
    R0_BLOCK: tl.constexpr = 384  # exact fit, no wasted lanes
    # r0_mask removed entirely
    val = tl.load(ptr, mask=xmask)  # no r0_mask overhead

